// Accepts ANY TradingView body. Never drops a signal: if it can't be parsed, the raw text is shown.
const KEY = 'change-me';
const ACT = {'1':'BUY CALLS','-1':'BUY PUTS','2':'SELL HALF CALLS','-2':'SELL HALF PUTS','3':'EXIT CALLS','-3':'EXIT PUTS'};
const STR = {'1':'S1 ORB 30m','2':'S2 SWEEP REVERSAL','3':'S3 VWAP','4':'S4 OPENING DRIVE','5':'S5 TREND PULLBACK','6':'S6 TLP PATIENCE'};
const store = $getWorkflowStaticData('global');
store.signals = store.signals || [];
for (const item of $input.all()) {
  let b = item.json.body;
  if ((b == null || (typeof b === 'object' && Object.keys(b).length === 0)) && item.binary && item.binary.data) {
    b = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  }
  if (b == null) continue;
  let raw = typeof b === 'string' ? b : JSON.stringify(b);
  if (typeof b === 'string') {
    const cleaned = b.replace(/\[\[[^\]]*\]\]/g, 'null').replace(/\{\{[^}]*\}\}/g, 'null').replace(/\bNaN\b/g, 'null');
    try { b = JSON.parse(cleaned); } catch (e) { b = { ticker: '?', action: 'RAW', note: raw.slice(0, 300) }; }
  }
  if (b.src === 'cc-ac') {
    b.action = b.code == null ? 'SIGNAL (see chart)' : (ACT[String(Math.round(b.code))] || ('code ' + b.code));
    b.strategy = b.strat == null ? '' : (STR[String(Math.round(b.strat))] || '');
    delete b.code; delete b.strat; delete b.src;
  } else if (b.key !== undefined && b.key !== KEY) {
    b.note = 'KEY MISMATCH - check Webhook key in CC-Multi settings';
  }
  if (typeof b.rvol === 'number') b.rvol = Math.round(b.rvol * 10) / 10;
  delete b.key;
  b.received = new Date().toISOString();
  store.signals.unshift(b);
}
store.signals = store.signals.slice(0, 500);
return [{ json: { ok: true, stored: store.signals.length } }];

const PAGE_JS = "
var LS={get:function(k){try{return localStorage.getItem(k)}catch(e){return null}},set:function(k,v){try{localStorage.setItem(k,v)}catch(e){}}};
var ctx=null, soundOn=false;
function honk(){ if(!ctx) return; var t=ctx.currentTime;
  for(var i=0;i<3;i++){ var s=t+i*0.55;
    [370,466].forEach(function(f){ var o=ctx.createOscillator(), g=ctx.createGain(), lp=ctx.createBiquadFilter();
      o.type='sawtooth'; o.frequency.value=f; lp.type='lowpass'; lp.frequency.value=1800;
      g.gain.setValueAtTime(0.0001,s); g.gain.exponentialRampToValueAtTime(0.35,s+0.03); g.gain.setValueAtTime(0.35,s+0.38); g.gain.exponentialRampToValueAtTime(0.0001,s+0.45);
      o.connect(lp); lp.connect(g); g.connect(ctx.destination); o.start(s); o.stop(s+0.5); }); } }
function enableSound(){ try{ ctx=ctx||new (window.AudioContext||window.webkitAudioContext)(); ctx.resume(); soundOn=true;
  var b=document.getElementById('snd'); b.textContent='🔊 Sound ON (test honk played)'; b.style.background='#16a34a'; honk(); }catch(e){} }
function etNow(){ var p=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  var o={}; p.forEach(function(x){o[x.type]=x.value}); return {wd:o.weekday, m:(+o.hour%24)*60+(+o.minute), day:o.year+'-'+o.month+'-'+o.day}; }
function fire(key){ if(LS.get('cc_honk_'+key)) return; LS.set('cc_honk_'+key,'1'); if(soundOn) honk(); }
function check(){
  var n=etNow(), wk=['Sat','Sun'].indexOf(n.wd)<0, ban=document.getElementById('banner');
  var inL = wk && n.m>=750 && n.m<840, after = wk && n.m>=840 && n.m<850;
  if(inL){ ban.style.display='block'; ban.style.background='#7c3aed'; ban.innerHTML='🍔 LUNCH BREAK — STOP: NO NEW TRADES until 2:00 PM ET<br><small>Open trades are still managed — follow SELL alerts</small>'; fire(n.day+'_start'); }
  else if(after){ ban.style.display='block'; ban.style.background='#0891b2'; ban.innerHTML='✅ LUNCH OVER — TRADING RESUMES<br><small>New entries allowed again</small>'; fire(n.day+'_end'); }
  else { ban.style.display='none'; }
  var app=document.getElementById('app'), last=app.getAttribute('data-lunch');
  if(last){ fire('alert_'+last); }
}
function refresh(){ fetch(location.href,{cache:'no-store'}).then(function(r){return r.text()}).then(function(t){
  var d=new DOMParser().parseFromString(t,'text/html'), na=d.getElementById('app'); if(na){ var a=document.getElementById('app'); a.innerHTML=na.innerHTML; a.setAttribute('data-lunch',na.getAttribute('data-lunch')||''); } check(); }).catch(function(){}); }
(function(){ var app=document.getElementById('app'), l=app.getAttribute('data-lunch'); if(l) LS.set('cc_honk_alert_'+l,'1');
  var n=etNow(); if(n.m>=750&&n.m<840) LS.set('cc_honk_'+n.day+'_start','1'); if(n.m>=840&&n.m<850) LS.set('cc_honk_'+n.day+'_end','1');
  check(); setInterval(check,5000); setInterval(refresh,10000); })();
";
const s = ($getWorkflowStaticData('global').signals || []);
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const col = a => /LUNCH BREAK/.test(a) ? '#7c3aed' : /LUNCH OVER/.test(a) ? '#0891b2' : /BUY CALLS/.test(a) ? '#16a34a' : /BUY PUTS/.test(a) ? '#dc2626' : /HALF/.test(a) ? '#f59e0b' : /POSSIBLE/.test(a) ? '#a16207' : '#6b7280';
const lastLunch = s.find(x => /LUNCH/.test(String(x.action || '')));
const lunchId = lastLunch ? esc(String(lastLunch.time || '') + '|' + (/OVER/.test(lastLunch.action) ? 'end' : 'start')) : '';
const rows = s.map(x => `<tr><td>${esc(x.time)}</td><td><b>${esc(x.ticker)}</b></td><td style="color:#fff;background:${col(x.action)};font-weight:${/LUNCH/.test(x.action) ? 'bold' : 'normal'}">${esc(x.action)}</td><td>${esc(x.strategy)}</td><td>${esc(x.price)}</td><td>${esc(x.stop)}</td><td>${esc(x.t1)}</td><td>${esc(x.t2)}</td><td>${x.rvol == null ? '' : esc(x.rvol) + 'x'}</td><td style="color:#9ca3af">${esc(x.note)}</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CC Signals</title><style>body{font-family:system-ui;background:#0b0f14;color:#e5e7eb;margin:16px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:6px 8px;border-bottom:1px solid #1f2937;text-align:left}th{color:#9ca3af}#banner{display:none;color:#fff;font-size:26px;font-weight:800;text-align:center;padding:18px;border-radius:10px;margin:12px 0}#banner small{font-size:15px;font-weight:500}#snd{background:#dc2626;color:#fff;border:0;border-radius:8px;padding:10px 14px;font-size:15px;cursor:pointer}.wrap{overflow-x:auto}</style></head><body><h2>Chart Commander signals</h2><button id="snd" onclick="enableSound()">🔇 Click once to turn ON the honk sound</button><div id="banner"></div><p style="color:#9ca3af">Updates every 10s (keep this page open). Newest first. Times ET.</p><div id="app" data-lunch="${lunchId}"><div class="wrap"><table><tr><th>Time</th><th>Ticker</th><th>Action</th><th>Strategy</th><th>Price</th><th>Stop</th><th>T1</th><th>T2</th><th>Vol</th><th>Note</th></tr>${rows || '<tr><td colspan=10>No signals yet</td></tr>'}</table></div></div><script>` + PAGE_JS + `</script></body></html>`;
return [{ json: { html } }];
